static int handle_octopus ( int count , const char * * args , int show_all ) { struct commit_list * revs = NULL ; struct commit_list * result , * rev ; int i ; for ( i = count - 1 ; i >= 0 ; i -- ) { commit_list_insert ( get_commit_reference ( args [ i ] ) , & revs ) ; } result = get_octopus_merge_bases ( revs ) ; free_commit_list ( revs ) ; reduce_heads_replace ( & result ) ; for ( rev = result ; rev ; rev = rev -> next ) { printf ( "%s\n" , oid_to_hex ( & rev -> item -> object . oid ) ) ; if ( ! show_all ) { break ; } } free_commit_list ( result ) ; return 0 ; } 